  ('CDE_BENEFIT_TEXT', 1, 'Benefit description', 'Plan benefit', 'other', 'Free-text description of the benefit attached to the plan, where one exists.', NULL, 'low', FALSE, NULL, 5.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'BNFT_TXT', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', current_timestamp(), current_user(), current_timestamp(), 'Registered so that its shadow rule names an element, as every rule must. Low: 75% blank is probably an optional field, which is exactly why the rule is still in shadow.'),
