  ('CDE_CUST_KEY', 1, 'Customer record key', 'Customer key', 'account_id', 'The surrogate key of the contact record. Every subscription points at one; a key that is not unique or that a subscription cannot resolve is a broken customer, whatever else is right about the row.', '^\\d{7}$', 'critical', FALSE, NULL, 0.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'CTCT_KEY', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', current_timestamp(), current_user(), current_timestamp(), 'Uniqueness by column match; the orphan check is cross-table, carries no target_column, and attaches by tag -- it is a rule about whether this key resolves, so this is its element.'),
  ('CDE_NETWORK_TECH', 1, 'Network technology', 'Access technology', 'other', 'The network the service runs on -- 4G, 5G, NBN and its variants.', NULL, 'medium', FALSE, NULL, 2.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'NTWK_TECH_NM', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', current_timestamp(), current_user(), current_timestamp(), ''),
  ('CDE_PREF_LANGUAGE', 1, 'Preferred language', 'Contact language', 'other', 'The language the contact prefers to be served in.', NULL, 'low', FALSE, NULL, 5.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'PREF_LANG_NM', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', current_timestamp(), current_user(), current_timestamp(), 'Its only rule is in shadow, so this element registers with no active rule against it -- the no_rule finding, present in the register on purpose.'),
