  ('CDE_SUBS_ACTIVATION', 1, 'Service activation timestamps', 'Activation date', 'other', 'When the service was first activated and when it was originally provisioned. The start of billing and of the contract term.', '^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}$', 'high', FALSE, 'Telecommunications Consumer Protections Code C628 — billing accuracy', 0.5, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'ORIG_ACTV_TS', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0), named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'INIT_ACTV_TS', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', current_timestamp(), current_user(), current_timestamp(), ''),
