  ('CDE_SUBS_STATUS', 1, 'Subscription status and reason', 'Subscription lifecycle status', 'other', 'Whether the subscription is active, cancelled or suspended, and why. The reason is only meaningful once the status is something other than active.', NULL, 'high', FALSE, NULL, 0.5, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'SUBS_STTS_KEY', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0), named_struct('target_table', 'workspace.dq_triage.dq_mock_subs_c', 'target_column', 'SUBS_STTS_RSN_KEY', 'populated_when', 'the subscription is not active', 'expected_scope_filter', 'SUBS_STTS_KEY <> 1', 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Subscription', 'dq-stewards-subscription', 'registered', current_timestamp(), current_user(), current_timestamp(), 'Two bindings, one rule: the reason is checked, the status itself is not. The status binding is a no_rule finding until somebody writes one.'),
  ('CDE_VULNERABLE_CUSTOMER', 1, 'Vulnerable customer indicator', 'Special-care status', 'other', 'Whether the contact is recorded as needing special care -- financial hardship, accessibility, or another vulnerability the business must act on. A flag that is never set is a customer never protected.', '^[YN]$', 'critical', TRUE, 'Telecommunications Consumer Protections Code C628 — vulnerable customers and financial hardship', 0.0, array(named_struct('target_table', 'workspace.dq_triage.dq_mock_ctct_c', 'target_column', 'SPCL_CARE_STTS', 'populated_when', NULL, 'expected_scope_filter', NULL, 'binding_status', 'bound', 'discovered_by', 'manual', 'confidence', 1.0)), 'Customer', 'dq-stewards-customer', 'registered', current_timestamp(), current_user(), current_timestamp(), 'The pilot data reads \'N\' on all 1000 rows, and the variance rule that watches it says so. Whether that is a defaulted field or a population with no vulnerable customers is COH-F\'s open question.');

